        uint totalSupply=IERC20(token).balanceOf(0x000000000000000000000000000000000000dEaD);
        if(totalSupply < IERC20(token).totalSupply()/10){
           IERC20(token).transfer(0x000000000000000000000000000000000000dEaD,amount);
